import os
import re
import unicodedata
from pathlib import PurePosixPath
from flask import Flask, request, send_file, abort, session, jsonify
from werkzeug.utils import secure_filename
import hashlib
import hmac
import secrets

app = Flask(__name__)
app.secret_key = secrets.token_hex(32)

BASE_DIR = '/srv/user_files'
ALLOWED_EXTENSIONS = {'.txt', '.pdf', '.png', '.jpg', '.doc', '.docx'}

def get_user_directory(user_id):
    """Get the sandboxed directory for a user."""
    safe_id = re.sub(r'[^a-zA-Z0-9_-]', '', str(user_id))
    return os.path.join(BASE_DIR, safe_id)

def validate_filename(filename):
    """Validate that filename is safe and has allowed extension."""
    if not filename or len(filename) > 255:
        return False
    # Block obvious traversal attempts
    if '..' in filename or filename.startswith('/'):
        return False
    # Check extension
    ext = os.path.splitext(filename)[1].lower()
    if ext not in ALLOWED_EXTENSIONS:
        return False
    return True

def normalize_path(filepath):
    """Normalize unicode characters in the path for consistent storage."""
    # NFKC normalization decomposes compatibility characters
    normalized = unicodedata.normalize('NFKC', filepath)
    return normalized

def sanitize_path_component(component):
    """Remove potentially dangerous characters from a path component."""
    # Only allow ASCII letters, digits, dots, hyphens, underscores
    cleaned = re.sub(r'[^a-zA-Z0-9.\-_ ]', '', component)
    return cleaned

def resolve_user_path(user_id, requested_path):
    """Safely resolve a user's requested file path within their directory."""
    user_dir = get_user_directory(user_id)

    # Normalize the requested path
    normalized_request = normalize_path(requested_path)

    # Split into components and sanitize each
    parts = normalized_request.replace('\\', '/').split('/')
    sanitized_parts = []
    for part in parts:
        if part == '' or part == '.':
            continue
        sanitized = sanitize_path_component(part)
        if sanitized and sanitized != '..':
            sanitized_parts.append(sanitized)

    # Reconstruct the path
    relative_path = os.path.join(*sanitized_parts) if sanitized_parts else ''
    full_path = os.path.join(user_dir, relative_path)

    # Final safety check: resolve and verify containment
    resolved = os.path.realpath(full_path)
    user_dir_resolved = os.path.realpath(user_dir)

    if not resolved.startswith(user_dir_resolved + os.sep) and resolved != user_dir_resolved:
        return None

    return resolved

@app.route('/api/files/download')
def download_file():
    """Download a file from the user's directory."""
    if 'user_id' not in session:
        abort(401)

    user_id = session['user_id']
    filename = request.args.get('name', '')
    subfolder = request.args.get('folder', '')

    if not validate_filename(filename):
        abort(400, 'Invalid filename')

    # Validate subfolder too
    if subfolder and ('..' in subfolder or subfolder.startswith('/')):
        abort(400, 'Invalid folder')

    # Construct the requested path
    if subfolder:
        requested_path = subfolder + '/' + filename
    else:
        requested_path = filename

    resolved_path = resolve_user_path(user_id, requested_path)
    if resolved_path is None:
        abort(403, 'Access denied')

    if not os.path.isfile(resolved_path):
        abort(404)

    return send_file(resolved_path)

@app.route('/api/files/metadata')
def file_metadata():
    """Get metadata about a file."""
    if 'user_id' not in session:
        abort(401)

    user_id = session['user_id']
    filepath = request.args.get('path', '')

    if not filepath:
        abort(400)

    # Apply unicode normalization for consistent lookup
    normalized = normalize_path(filepath)

    # Validate the normalized path
    if validate_filename(os.path.basename(normalized)):
        resolved = resolve_user_path(user_id, normalized)
        if resolved and os.path.exists(resolved):
            stat = os.stat(resolved)
            return jsonify({
                'name': os.path.basename(resolved),
                'size': stat.st_size,
                'modified': stat.st_mtime
            })

    abort(404)

@app.route('/api/files/share', methods=['POST'])
def share_file():
    """Generate a share link for a file."""
    if 'user_id' not in session:
        abort(401)

    user_id = session['user_id']
    data = request.get_json()
    if not data or 'filename' not in data:
        abort(400)

    filename = data['filename']
    folder = data.get('folder', '')

    if not validate_filename(filename):
        abort(400, 'Invalid filename')

    if folder and ('..' in folder or folder.startswith('/')):
        abort(400, 'Invalid folder')

    if folder:
        requested_path = folder + '/' + filename
    else:
        requested_path = filename

    resolved = resolve_user_path(user_id, requested_path)
    if resolved is None or not os.path.isfile(resolved):
        abort(404)

    # Generate share token (use full HMAC-SHA256 digest to avoid weak/truncated tokens)
    share_data = f"{user_id}:{resolved}:{secrets.token_hex(8)}"
    token = hmac.new(app.secret_key.encode(), share_data.encode(), hashlib.sha256).hexdigest()

    return jsonify({'share_url': f'/shared/{token}', 'expires_in': 3600})

@app.route('/api/files/search')
def search_files():
    """Search for files in user's directory."""
    if 'user_id' not in session:
        abort(401)

    user_id = session['user_id']
    query = request.args.get('q', '')

    if not query or len(query) < 2:
        abort(400)

    user_dir = get_user_directory(user_id)
    user_dir_resolved = os.path.realpath(user_dir)

    results = []
    if os.path.isdir(user_dir_resolved):
        for root, dirs, files in os.walk(user_dir_resolved):
            for f in files:
                if query.lower() in f.lower():
                    rel = os.path.relpath(os.path.join(root, f), user_dir_resolved)
                    results.append(rel)

    return jsonify({'results': results[:50]})

if __name__ == '__main__':
    app.run(host='127.0.0.1', port=5000)
